theorem absolute_masses_le {B : ℕ} {sigma kappa c0 : ℝ} {d : MediumAtom}
    (hd : MediumAdmissible B sigma kappa c0 d) {H : ℝ} (hH : 0 < H) {p : ℕ}
    (hp : p ∈ d.primitiveFirstFactorCarrier) (m : ℕ) :
    (∑ l ∈ labels d p m, ‖coeff d p m l‖) ≤ CommonPM2FiniteFold.rowSum d p m ∧
    (∑ l ∈ labels d p m, if keep d H m l then 0 else ‖coeff d p m l‖) ≤
      CommonPM2FiniteFold.rowSum d p m / H
